import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.DfDAiEgj.js";const l="/2bPM/img/Robo-Advisor.png",m=JSON.parse('{"title":"智能顾投","description":"","frontmatter":{},"headers":[],"relativePath":"ai-finance/Robo-Advisor.md","filePath":"ai-finance/Robo-Advisor.md","lastUpdated":null}'),n={name:"ai-finance/Robo-Advisor.md"};function i(h,e,s,p,c,d){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="智能顾投" tabindex="-1">智能顾投 <a class="header-anchor" href="#智能顾投" aria-label="Permalink to &quot;智能顾投&quot;">​</a></h1><p>智能投顾，又称“机器人投顾”，大多数情况下，通过在线调查问卷来获取投资者关于投资目标、投资期限、收入、资产和风险，来了解投资者的风险偏好以及投资偏好，从而结合算法模型为用户制定个性化的资产配置方案，包括动态调仓，实时监控等功能。相较于传统的投资顾问，机器人投顾通常试图为投资者提供更为便宜的投顾服务，而且很多时候资金门槛也更低。不过，这些机器人投顾提供的服务内容、投资方法和特色都千差万别。 <a href="https://www.zhihu.com/question/40505552/answer/151307145" target="_blank" rel="noreferrer">2</a></p><h2 id="作用" tabindex="-1">作用 <a class="header-anchor" href="#作用" aria-label="Permalink to &quot;作用&quot;">​</a></h2><p>智能投顾主要是帮助客户简化理财流程，享受更方便快捷的服务。传统上客户往往要亲自去银行理财专柜，填写若干复杂的问卷，看很多理财产品的资料，而智能投顾可以让用户足不出户，在移动端或者pc端上花上几分钟便可完成整个理财的流程。但是这并不能说明智能投顾可以保证客户理财的收益率，只能说智能投顾可以帮助客户用最短的时间，找到用户最喜欢的，最合适的投资标的。</p><h2 id="传统的投顾" tabindex="-1">传统的投顾 <a class="header-anchor" href="#传统的投顾" aria-label="Permalink to &quot;传统的投顾&quot;">​</a></h2><p>投资顾问。证券投资顾问业务的近代起源可以追溯到传统的私人银行的理财服务业务，私人银行业务在欧洲已经有上百年的历史，最初是瑞士银行专门向富有的上流社会群体提供私密的、一对一的服务。<a href="https://www.zhihu.com/question/40505552/answer/1403622645" target="_blank" rel="noreferrer">3</a></p><h2 id="智能顾投的历史7" tabindex="-1">智能顾投的历史<a href="https://www.cnblogs.com/dhcn/p/12093586.html" target="_blank" rel="noreferrer">7</a> <a class="header-anchor" href="#智能顾投的历史7" aria-label="Permalink to &quot;智能顾投的历史[7]&quot;">​</a></h2><p>智能投顾最早起源于美国，发展历程大致可分为三个阶段。</p><ol><li><p>在线投顾阶段：20世纪90年代末期，可供投资者选择应用的投资分析工具的技术水平和规模开始扩大。2005年，FINRA 颁布 NASD IM2210-6 Requirements for the Use of Investment Analysis Tools 规章，允许证券自营商将投资分析工具（investment analysis tools）直接让投资者使用，投资者可以利用投资分析工具进行不同投资策略的投资收益分析，对收益和风险有更好的把控。此后，在线资产管理服务规模迅速增长，更多长尾客户在此阶段受益。此阶段的特点主要是机器智能应用比较有限，主要应用领域是投资组合分析。</p></li><li><p>机器人投顾阶段：2008年～2015年期间，大量新兴科技企业开始为客户直接提供各类基于机器学习的 “数字化投顾工具”，机器人投顾商业模式开始发展。这些公司开发的面向客户的投顾工具提供的功能之前只被金融从业者应用，目前已经广泛被客户所直接应用。在这个阶段的很多实际应用案例中，证券公司对他们的“数字化投顾工具”提供的投资策略负责。</p></li><li><p>人工智能投顾阶段：2015年至今，以大数据为基础的深度学习被广泛应用，人工智能技术取得突破型进展。智能投顾服务商和科技企业开始尝试开发能够完全消除人类参与投资管理价值链的人工智能系统。目前包括国外的Bridge Water、Wealthfront，国内的弥财等都已经实现了这样的系统开发和商业化运营。通常采用“人工智能+云计算”体系结构的服务商，在计算设备和软件开发方面投资巨大（少则1-2亿，多则几十亿），能够同时服务千万、亿级别的海量用户。<a href="https://www.cnblogs.com/dhcn/p/12093586.html" target="_blank" rel="noreferrer">7</a></p></li></ol><h2 id="智能投顾分类" tabindex="-1">智能投顾分类 <a class="header-anchor" href="#智能投顾分类" aria-label="Permalink to &quot;智能投顾分类&quot;">​</a></h2><p><img src="'+l+'" alt="智能投顾分类4"></p><h2 id="资产配置" tabindex="-1">资产配置 <a class="header-anchor" href="#资产配置" aria-label="Permalink to &quot;资产配置&quot;">​</a></h2><p>投资收益中资产配置的重要性，而资产配置又是投资顾问的重要职能，中国理财市场里存在大量挣钱的金融产品，也有大量低学历的金融销售，但恰恰缺少大量优秀的投资顾问，缺少专业人才给投资用户做资产配置，这也是为什么中国大部分投资用户会赔钱。 <a href="https://www.zhihu.com/question/40505552" target="_blank" rel="noreferrer">1</a></p><h2 id="优点-5" tabindex="-1">优点 <a href="https://www.douban.com/note/557874669/" target="_blank" rel="noreferrer">5</a> <a class="header-anchor" href="#优点-5" aria-label="Permalink to &quot;优点 [5]&quot;">​</a></h2><ol><li>最优配置。最优配置是匹配给每一个不同的投资人的，因为每个人的情况不一样，有的人可能能够承受5%的亏损，有的人却亏一点就夜不能寐；有的人这笔钱可能是马上就要用，但是有的人这笔钱可以放很久。所以不同的人所需要的资产配置解决方案应该是不一样的，它是针对个人的最优配置。</li><li>降低服务门槛。传统上的资产配置是由私人银行加主权基金这些大的机构使用的，通过一个机器人的解决方案，能够把这个服务门槛降到一个普通的中产阶级家庭和新富裕的人群来使用。</li><li>战胜人性（非常有效的一点）。在投资过程中，贪婪和恐惧永远在两端摇摆，人性往往使其做出错误的判断。如果你是一个机器人，则会非常冷静，在恐惧的时候也不会做出错误的决定，从而帮助你去战胜人性的弱点。</li><li>它会帮你降低交易成本，因为智能投顾很多时候是通过 ETF 交易，由于背后是大数据的抓取和海量运算，节省了人工顾问的成本，以及线下开设网点的成本。</li><li>机器人的投顾跟投资人的利益会保持一致。传统的投顾往往根据交易的佣金来获利，所以他们之间存在潜在的利益冲突，他希望你能够频繁交易。但其实频繁的交易可能会导致损失，而机器人投顾不以收取佣金为目的，不以频繁交易为目的，跟你的利益是一致的。</li></ol><h2 id="公司" tabindex="-1">公司 <a class="header-anchor" href="#公司" aria-label="Permalink to &quot;公司&quot;">​</a></h2><p>目前我国提供此服务的公司很多，其中银行系（如广发智投、招行摩羯智投、工行“AI”投等）、基金系（如南方基金超级智投宝、广发基金基智理财等）、大型互联网公司系（如百度金融、京东智投、同花顺）和第三方创业公司（如弥财、蓝海财富、拿铁财经等）都在智能投顾上有所应用。<a href="http://www.szama.org/html356/356/5382.html" target="_blank" rel="noreferrer">6</a></p><h2 id="_2c到2b" tabindex="-1">2C到2B <a class="header-anchor" href="#_2c到2b" aria-label="Permalink to &quot;2C到2B&quot;">​</a></h2><p>近年来我们看到，众多金融科技公司正从市场的颠覆者，转变为与传统机构的合作者、赋能者，从另一个角度引领整个市场的创新活力。从2C模式转变成2B模式是财富管理金融科技公司快速、低成本积累管理资产规模、客户数据与实战场景的有效手段。以美国领先的智能投顾金融科技公司Betterment为例，2014年Betterment推出2B产品线Betterment for Advisors，将智能投顾工具开放给超过300家中小财富管理机构，并为富达集团等大机构的投资顾问提供智能投顾支持。2B产品帮助Betterment的管理资产在四年内迅速突破140亿美元34，与专注于2C模式时经历七年发展规模仍不足20亿美元相比，实现了跨越式的增长。<a href="https://www.thepaper.cn/newsDetail_forward_11822405" target="_blank" rel="noreferrer">8</a></p><p>TODO: 智能投顾是什么？「智能」体现在哪些方面？ - 知乎 <a href="https://www.zhihu.com/question/40505552/answer/137963123" target="_blank" rel="noreferrer">https://www.zhihu.com/question/40505552/answer/137963123</a></p><p>智能顾投： <a href="https://t.qidianla.com/1162362.html" target="_blank" rel="noreferrer">https://t.qidianla.com/1162362.html</a></p><p>智能投顾面面观之AI慕课： <a href="https://www.jianshu.com/p/437c895794e0" target="_blank" rel="noreferrer">https://www.jianshu.com/p/437c895794e0</a></p>',22)])])}const w=a(n,[["render",i]]);export{m as __pageData,w as default};
